// lib/core/audio_service.dart
// Demeter – Farmer Edge Ingestion Module
// Records farmer voice input to the OS filesystem as .ogg (Opus).
//
// RULES ENFORCED:
//   ✗  No Base64 encoding
//   ✗  No SQLite blob storage
//   ✓  Files land in getApplicationDocumentsDirectory()/demeter/audio/
//   ✓  Returns the absolute path for metadata-only DB insertion

import 'dart:io';
import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';
import 'package:record/record.dart';

// ---------------------------------------------------------------------------
// Exceptions
// ---------------------------------------------------------------------------

class AudioServiceException implements Exception {
  const AudioServiceException(this.message, [this.cause]);
  final String message;
  final Object? cause;

  @override
  String toString() =>
      'AudioServiceException: $message${cause != null ? ' (caused by $cause)' : ''}';
}

// ---------------------------------------------------------------------------
// AudioSession – represents one recording lifecycle
// ---------------------------------------------------------------------------

class AudioSession {
  AudioSession._({
    required this.sessionId,
    required this.filePath,
  });

  final String sessionId;  // matches MicroLot.id
  final String filePath;   // absolute OS path → stored in DB, not the file

  File get file => File(filePath);

  bool get fileExists => file.existsSync();

  /// Size in bytes; 0 if the file doesn't exist yet (recording in progress).
  int get fileSizeBytes => fileExists ? file.lengthSync() : 0;

  @override
  String toString() => 'AudioSession($sessionId, $filePath)';
}

// ---------------------------------------------------------------------------
// AudioService  (one recorder instance per app lifecycle)
// ---------------------------------------------------------------------------

class AudioService {
  AudioService._();
  static final AudioService instance = AudioService._();

  final AudioRecorder _recorder = AudioRecorder();
  AudioSession? _activeSession;

  bool get isRecording => _activeSession != null;

  // ── Directory bootstrap ───────────────────────────────────────────────────

  /// Returns (and creates if absent) the canonical audio storage directory.
  /// Path: <Documents>/demeter/audio/
  /// This is private, sandboxed storage – no READ_EXTERNAL_STORAGE needed.
  Future<Directory> _getAudioDir() async {
    final docs = await getApplicationDocumentsDirectory();
    final dir = Directory(p.join(docs.path, 'demeter', 'audio'));
    if (!dir.existsSync()) {
      await dir.create(recursive: true);
    }
    return dir;
  }

  // ── Recording lifecycle ───────────────────────────────────────────────────

  /// Starts recording a new session keyed by [lotId] (UUID).
  ///
  /// The caller must have already requested MICROPHONE permission.
  /// Throws [AudioServiceException] if:
  ///   - a recording is already in progress
  ///   - microphone permission is not granted
  ///   - an OS-level recording error occurs
  Future<AudioSession> startRecording(String lotId) async {
    if (_activeSession != null) {
      throw const AudioServiceException(
        'Cannot start a new session: a recording is already in progress.',
      );
    }

    final hasPermission = await _recorder.hasPermission();
    if (!hasPermission) {
      throw const AudioServiceException(
        'Microphone permission not granted. '
        'Request permission before calling startRecording().',
      );
    }

    try {
      final audioDir = await _getAudioDir();
      // filename: <lotId>.ogg – UUID ensures no collisions across sessions.
      final filePath = p.join(audioDir.path, '$lotId.ogg');

      await _recorder.start(
        const RecordConfig(
          encoder: AudioEncoder.opus, // Opus → OGG container; excellent for speech
          bitRate: 32000,             // 32 kbps: intelligible speech on 2 GB RAM devices
          sampleRate: 16000,          // 16 kHz: standard for ASR pipelines
          numChannels: 1,             // Mono – halves file size vs. stereo
        ),
        path: filePath,
      );

      _activeSession = AudioSession._(sessionId: lotId, filePath: filePath);
      _log('Recording started → $filePath');
      return _activeSession!;
    } catch (e) {
      _activeSession = null;
      throw AudioServiceException('Failed to start recording', e);
    }
  }

  /// Stops the active recording and returns the finalised [AudioSession].
  ///
  /// Throws [AudioServiceException] if no session is active or if the
  /// recorder fails to stop cleanly.
  Future<AudioSession> stopRecording() async {
    if (_activeSession == null) {
      throw const AudioServiceException(
        'stopRecording() called but no recording is in progress.',
      );
    }

    try {
      // `stop()` flushes buffers and closes the file handle.
      final savedPath = await _recorder.stop();
      final session = _activeSession!;
      _activeSession = null;

      if (savedPath == null || savedPath.isEmpty) {
        throw const AudioServiceException(
          'Recorder returned a null/empty path after stop. '
          'File may be corrupted.',
        );
      }

      // Sanity-check: ensure the file was actually written.
      final file = File(savedPath);
      if (!file.existsSync() || file.lengthSync() == 0) {
        throw AudioServiceException(
          'Audio file is missing or empty after recording: $savedPath',
        );
      }

      _log('Recording stopped → ${file.lengthSync()} bytes at $savedPath');
      return session;
    } catch (e, st) {
      _activeSession = null;
      if (e is AudioServiceException) rethrow;
      throw AudioServiceException('Failed to stop recording', e);
    }
  }

  /// Cancels an in-progress recording and deletes any partial file.
  /// Safe to call even if no recording is active.
  Future<void> cancelRecording() async {
    if (_activeSession == null) return;
    final session = _activeSession!;
    _activeSession = null;

    try {
      await _recorder.cancel();
    } catch (_) {
      // Best-effort cancel – proceed to cleanup regardless.
    }

    // Remove the partial .ogg file to avoid polluting storage.
    final file = session.file;
    if (file.existsSync()) {
      try {
        await file.delete();
        _log('Cancelled – partial file deleted: ${file.path}');
      } catch (e) {
        _log('Warning: could not delete partial file: ${file.path} → $e');
      }
    }
  }

  // ── File management ───────────────────────────────────────────────────────

  /// Deletes the audio file for the given [filePath].
  /// Called by the sync worker after confirmed upload to reclaim storage.
  Future<bool> deleteAudioFile(String filePath) async {
    final file = File(filePath);
    if (!file.existsSync()) {
      _log('deleteAudioFile: file not found at $filePath – skipping.');
      return false;
    }
    try {
      await file.delete();
      _log('Deleted audio file: $filePath');
      return true;
    } catch (e) {
      _log('Failed to delete $filePath: $e');
      return false;
    }
  }

  /// Returns the total size (in bytes) of all stored .ogg files.
  /// Useful for a "storage used" display in the farmer UI.
  Future<int> totalAudioStorageBytes() async {
    try {
      final dir = await _getAudioDir();
      return dir
          .listSync(recursive: false)
          .whereType<File>()
          .where((f) => f.path.endsWith('.ogg'))
          .fold<int>(0, (sum, f) => sum + f.lengthSync());
    } catch (_) {
      return 0;
    }
  }

  // ── Disposal ──────────────────────────────────────────────────────────────

  Future<void> dispose() async {
    await _recorder.dispose();
  }

  void _log(String msg) {
    // ignore: avoid_print
    print('[AudioService] $msg');
  }
}

// lib/core/sync_worker.dart
// Demeter – Farmer Edge Ingestion Module
// WorkManager callback + Dio multipart upload.
//
// ARCHITECTURE NOTES:
//   • callbackDispatcher() is a top-level function – WorkManager requirement.
//     It runs in its own Dart isolate (not the main Flutter isolate).
//   • All dependencies (DB, Dio) are re-initialised inside the worker because
//     the isolate has no access to the main isolate's singletons.
//   • Files are streamed (not buffered) – avoids OOM on 2 GB RAM devices.
//   • A single failed upload marks that lot as 'failed' and continues the
//     loop; it does NOT abort the entire sync batch.

import 'dart:io';
import 'package:dio/dio.dart';
import 'package:workmanager/workmanager.dart';

import 'database_helper.dart'; // MicroLot, SyncStatus, DatabaseHelper

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/// Unique task name registered with WorkManager.
const kSyncTaskName = 'demeter.farmerEdgeSync';

/// Unique task identifier (must match registration in main.dart).
const kSyncTaskUniqueName = 'demeter_sync_periodic';

/// Backend ingest endpoint. Replace with production URL before release.
const _kIngestUrl = 'https://api.demeter.example/api/v1/ingest';

/// Dio connect/receive timeouts – conservative for flaky rural networks.
const _kConnectTimeout = Duration(seconds: 30);
const _kReceiveTimeout = Duration(seconds: 120); // large audio may be slow

// ---------------------------------------------------------------------------
// WorkManager callback dispatcher  (MUST be top-level)
// ---------------------------------------------------------------------------

/// Entry point called by WorkManager in a background isolate.
/// Register this in main.dart BEFORE runApp().
@pragma('vm:entry-point')
void callbackDispatcher() {
  Workmanager().executeTask((taskName, inputData) async {
    if (taskName != kSyncTaskName) {
      // Unknown task – return success to prevent WorkManager from retrying.
      return Future.value(true);
    }

    try {
      await _runSyncCycle();
      return Future.value(true);
    } catch (e) {
      // Returning false signals WorkManager to retry with back-off.
      _log('Sync cycle failed with unhandled exception: $e');
      return Future.value(false);
    }
  });
}

// ---------------------------------------------------------------------------
// Core sync logic
// ---------------------------------------------------------------------------

Future<void> _runSyncCycle() async {
  final db = DatabaseHelper.instance;
  final uploader = _IngestUploader();

  final pending = await db.getPendingLots();
  if (pending.isEmpty) {
    _log('No pending lots – sync cycle complete.');
    return;
  }

  _log('Starting sync cycle for ${pending.length} pending lot(s).');

  final successIds = <String>[];

  for (final lot in pending) {
    final file = File(lot.audioFilePath);

    // ── Guard: file must exist before attempting upload ──────────────────
    if (!file.existsSync()) {
      _log(
        'Audio file missing for lot ${lot.id}: ${lot.audioFilePath}. '
        'Marking as failed.',
      );
      await db.updateSyncStatus(lot.id, SyncStatus.failed);
      continue;
    }

    try {
      final uploaded = await uploader.uploadLot(lot, file);
      if (uploaded) {
        successIds.add(lot.id);
        _log('Uploaded lot ${lot.id} ✓');
      } else {
        // Server returned non-2xx – mark failed, do not retry this cycle.
        await db.updateSyncStatus(lot.id, SyncStatus.failed);
        _log('Upload rejected by server for lot ${lot.id} – marked failed.');
      }
    } on DioException catch (e) {
      _log('DioException for lot ${lot.id}: ${e.message}');
      // Network errors stay as 'pending' so WorkManager retries next cycle.
      // Permanent HTTP errors (4xx) are marked failed.
      if (_isPermanentHttpError(e)) {
        await db.updateSyncStatus(lot.id, SyncStatus.failed);
      }
      // else: leave as pending; WorkManager will retry via back-off schedule.
    } catch (e) {
      _log('Unexpected error uploading lot ${lot.id}: $e');
      // Conservative: leave as pending.
    }
  }

  // Batch-commit all successes in one transaction.
  if (successIds.isNotEmpty) {
    await db.markLotsAsSynced(successIds);
    _log('Marked ${successIds.length} lot(s) as synced.');
  }
}

/// Returns true for HTTP errors that will never succeed on retry (4xx, excl. 429).
bool _isPermanentHttpError(DioException e) {
  final code = e.response?.statusCode;
  if (code == null) return false;
  // 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 422 Unprocessable
  // are permanent. 429 Too Many Requests and 5xx are transient → keep as pending.
  return code >= 400 && code < 500 && code != 429;
}

// ---------------------------------------------------------------------------
// Uploader
// ---------------------------------------------------------------------------

class _IngestUploader {
  late final Dio _dio;

  _IngestUploader() {
    _dio = Dio(
      BaseOptions(
        connectTimeout: _kConnectTimeout,
        receiveTimeout: _kReceiveTimeout,
        headers: {
          // Add auth headers here (e.g. Bearer token from secure storage).
          'X-Demeter-Version': '1.0',
        },
      ),
    );
    // Interceptors for logging / token-refresh can be added here.
  }

  /// Streams [file] as multipart/form-data to the ingest endpoint.
  ///
  /// Returns true on HTTP 200/201, false on any other status.
  /// Throws [DioException] on network-level failures.
  Future<bool> uploadLot(MicroLot lot, File file) async {
    final fileSize = await file.length();

    // MultipartFile.fromFileSync would load the entire file into memory –
    // use the async factory instead to stream chunks and protect 2 GB RAM.
    final multipartFile = await MultipartFile.fromFile(
      file.path,
      filename: '${lot.id}.ogg',
      // Content-Type tells the backend this is Opus audio in an OGG container.
      contentType: DioMediaType('audio', 'ogg'),
    );

    final formData = FormData.fromMap({
      'lot_id': lot.id,
      'grade_hint': lot.tfliteGradeHint,
      'timestamp': lot.timestamp.toString(),
      'audio': multipartFile,
    });

    _log(
      'Uploading lot ${lot.id} | '
      'grade=${lot.tfliteGradeHint} | '
      'file=${file.path} | '
      'size=${_formatBytes(fileSize)}',
    );

    final response = await _dio.post<Map<String, dynamic>>(
      _kIngestUrl,
      data: formData,
      onSendProgress: (sent, total) {
        if (total > 0) {
          _log('  → ${lot.id}: ${(sent / total * 100).toStringAsFixed(1)}%');
        }
      },
    );

    return response.statusCode == 200 || response.statusCode == 201;
  }
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

String _formatBytes(int bytes) {
  if (bytes < 1024) return '${bytes}B';
  if (bytes < 1024 * 1024) return '${(bytes / 1024).toStringAsFixed(1)}KB';
  return '${(bytes / (1024 * 1024)).toStringAsFixed(2)}MB';
}

void _log(String msg) {
  // ignore: avoid_print
  print('[SyncWorker] $msg');
}

